macro_rules! deps {
    () => {
        String!();
        Link!();
        Name!();
        Note!();
        SubSectionRequirement!();
        Section!();
        Error!();
    };
}

macro_rules! Key {
    () => {
        deps!();
        # [doc = " A leaf-level entry in the git configuration, like `url` in `remote.origin.url`."] pub trait Key : std :: fmt :: Debug { # [doc = " The key's name, like `url` in `remote.origin.url`."] fn name (& self) -> & str ; # [doc = " See if `value` is allowed as value of this key, or return a descriptive error if it is not."] fn validate (& self , value : & BStr) -> Result < () , crate :: config :: tree :: key :: validate :: Error > ; # [doc = " The section containing this key. Git configuration has no free-standing keys, they are always underneath a section."] fn section (& self) -> & dyn Section ; # [doc = " The return value encodes three possible states to indicate subsection requirements"] # [doc = " * `None` = subsections may or may not be used, the most flexible setting."] # [doc = " * `Some([Requirement][SubSectionRequirement])` = subsections must or must not be used, depending on the value"] fn subsection_requirement (& self) -> Option < & SubSectionRequirement > { Some (& SubSectionRequirement :: Never) } # [doc = " Return the link to other resources, if available."] fn link (& self) -> Option < & Link > { None } # [doc = " Return a note about this key, if available."] fn note (& self) -> Option < & Note > { None } # [doc = " Return the name of an environment variable that would override this value (after following links until one is found)."] fn environment_override (& self) -> Option < & str > { let mut cursor = self . link () ? ; loop { match cursor { Link :: EnvironmentOverride (name) => return Some (name) , Link :: FallbackKey (next) => { cursor = next . link () ? ; } } } } # [doc = " Return the environment override that must be set on this key."] # [doc = " # Panics"] # [doc = " If no environment variable is set"] fn the_environment_override (& self) -> & str { self . environment_override () . expect ("BUG: environment override must be set") } # [doc = " Produce a name that describes how the name is composed. This is `core.bare` for statically known keys, or `branch.<name>.key`"] # [doc = " for complex ones."] fn logical_name (& self) -> String { let section = self . section () ; let mut buf = String :: new () ; let parameter = if let Some (parent) = section . parent () { buf . push_str (parent . name ()) ; buf . push ('.') ; None } else { self . subsection_requirement () . and_then (| requirement | match requirement { SubSectionRequirement :: Parameter (name) => Some (name) , SubSectionRequirement :: Never => None , }) } ; buf . push_str (section . name ()) ; buf . push ('.') ; if let Some (parameter) = parameter { buf . push ('<') ; buf . push_str (parameter) ; buf . push ('>') ; buf . push ('.') ; } buf . push_str (self . name ()) ; buf } # [doc = " The full name of the key for use in configuration overrides, like `core.bare`, or `remote.<subsection>.url` if `subsection` is"] # [doc = " not `None`."] # [doc = " May fail if this key needs a subsection, or may not have a subsection."] fn full_name (& self , subsection : Option < & BStr >) -> Result < BString , String > { let section = self . section () ; let mut buf = BString :: default () ; let subsection = match self . subsection_requirement () { None => subsection , Some (requirement) => match (requirement , subsection) { (SubSectionRequirement :: Never , Some (_)) => { return Err (format ! ("The key named '{}' cannot be used with non-static subsections." , self . logical_name ())) ; } (SubSectionRequirement :: Parameter (_) , None) => { return Err (format ! ("The key named '{}' cannot be used without subsections." , self . logical_name ())) } _ => subsection , } , } ; if let Some (parent) = section . parent () { buf . push_str (parent . name ()) ; buf . push (b'.') ; } buf . push_str (section . name ()) ; buf . push (b'.') ; if let Some (subsection) = subsection { debug_assert ! (section . parent () . is_none () , "BUG: sections with parameterized sub-sections must be top-level sections") ; buf . push_str (subsection) ; buf . push (b'.') ; } buf . push_str (self . name ()) ; Ok (buf) } # [doc = " Return an assignment with the keys full name to `value`, suitable for [configuration overrides][crate::open::Options::config_overrides()]."] # [doc = " Note that this will fail if the key requires a subsection name."] fn validated_assignment (& self , value : & BStr) -> Result < BString , validate_assignment :: Error > { self . validate (value) ? ; let mut key = self . full_name (None) . map_err (| message | validate_assignment :: Error :: Name { message }) ? ; key . push (b'=') ; key . push_str (value) ; Ok (key) } # [doc = " Return an assignment with the keys full name to `value`, suitable for [configuration overrides][crate::open::Options::config_overrides()]."] # [doc = " Note that this will fail if the key requires a subsection name."] fn validated_assignment_fmt (& self , value : & dyn std :: fmt :: Display ,) -> Result < BString , crate :: config :: tree :: key :: validate_assignment :: Error > { let value = value . to_string () ; self . validated_assignment (value . as_str () . into ()) } # [doc = " Return an assignment to `value` with the keys full name within `subsection`, suitable for [configuration overrides][crate::open::Options::config_overrides()]."] # [doc = " Note that this is only valid if this key supports parameterized sub-sections, or else an error is returned."] fn validated_assignment_with_subsection (& self , value : & BStr , subsection : & BStr ,) -> Result < BString , crate :: config :: tree :: key :: validate_assignment :: Error > { self . validate (value) ? ; let mut key = self . full_name (Some (subsection)) . map_err (| message | validate_assignment :: Error :: Name { message }) ? ; key . push (b'=') ; key . push_str (value) ; Ok (key) } }
    };
}

Key!()